class Solution {
public:
    int minCostToMoveChips(vector<int>& position) {

        int odd = 0, even = 0;

        for(auto i : position)
            if(i % 2)
                odd ++;
            else
                even ++;

        return min(odd, even);
    }
};

class Solution(object):
    def minCostToMoveChips(self, position):
        """
        :type position: List[int]
        :rtype: int
        """
        cnt1, cnt2 = 0, 0
        for p in position:
            if p % 2 == 0:
                cnt1 += 1
            else:
                cnt2 += 1
        return min(cnt1, cnt2)
